export const code = async (inputs) => {
  const PROMO_TYPE_FIXED = 'fixed_price'
  const PROMO_TYPE_PERCENT = 'discount_percent'

  const asArray = (value) => {
    if (Array.isArray(value)) return value
    if (value && typeof value === 'object' && Array.isArray(value.nodes)) return value.nodes
    if (value && typeof value === 'object' && value.body) {
      const body = value.body
      if (Array.isArray(body)) return body
      if (body && Array.isArray(body.nodes)) return body.nodes
    }
    return []
  }

  const fkId = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'object' && value.id != null) return String(value.id)
    return String(value)
  }

  const toNumber = (value) => {
    if (value == null || value === '') return null
    const n = Number(value)
    return Number.isFinite(n) ? n : null
  }

  const toDateString = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'string') {
      const trimmed = value.trim()
      return trimmed ? trimmed.slice(0, 10) : null
    }
    return null
  }

  const normalizePromoType = (value) => {
    const raw = String(value ?? '')
      .trim()
      .toLowerCase()
    if (raw === PROMO_TYPE_FIXED || raw === 'fixed') return PROMO_TYPE_FIXED
    if (
      raw === PROMO_TYPE_PERCENT ||
      raw === 'percent' ||
      raw === 'discount' ||
      raw === 'discount_percent'
    ) {
      return PROMO_TYPE_PERCENT
    }
    return null
  }

  const computePromoPrice = (listPrice, promo) => {
    if (promo.promoType === PROMO_TYPE_FIXED) {
      return promo.fixedPrice == null ? listPrice : promo.fixedPrice
    }
    if (promo.discountPercent == null) return listPrice
    return listPrice * (1 - promo.discountPercent / 100)
  }

  const promotionMatchesRow = (promo, itemId, itemGroupId, priceGroupId) => {
    const hasItem = Boolean(promo.itemId)
    const hasItemGroup = Boolean(promo.itemGroupId)
    const hasPriceGroup = Boolean(promo.itemPriceGroupId)
    if (!hasItem && !hasItemGroup && !hasPriceGroup) return false
    if (hasItem && (!itemId || promo.itemId !== itemId)) return false
    if (hasItemGroup && (!itemGroupId || promo.itemGroupId !== itemGroupId)) return false
    if (hasPriceGroup && (!priceGroupId || promo.itemPriceGroupId !== priceGroupId)) {
      return false
    }
    return true
  }

  const specificity = (promo) =>
    (promo.itemId ? 4 : 0) + (promo.itemGroupId ? 2 : 0) + (promo.itemPriceGroupId ? 1 : 0)

  const pickWinningPromotion = (matches) => {
    if (!matches.length) return null
    return (
      [...matches].sort((a, b) => {
        const spec = specificity(b) - specificity(a)
        if (spec !== 0) return spec
        if (a.dateStart !== b.dateStart) return a.dateStart < b.dateStart ? 1 : -1
        return a.id < b.id ? 1 : a.id > b.id ? -1 : 0
      })[0] ?? null
    )
  }

  const roundMoney = (value) => Math.round(value * 10000) / 10000
  const sameId = (a, b) => {
    if (a == null && b == null) return true
    if (a == null || b == null) return false
    return String(a) === String(b)
  }
  const sameMoney = (a, b) => (a == null ? false : Math.abs(a - b) < 1e-9)

  const payloadRoot = inputs.payload || {}
  const body =
    payloadRoot.body && typeof payloadRoot.body === 'object' ? payloadRoot.body : payloadRoot
  const timeZone = String(body.timeZone || inputs.timeZone || 'UTC')
  const today =
    typeof body.today === 'string' && body.today.trim()
      ? body.today.trim().slice(0, 10)
      : new Date().toISOString().slice(0, 10)

  const promotions = asArray(inputs.promotions)
  const items = asArray(inputs.items)
  const prices = asArray(inputs.prices)

  const activePromotions = []
  for (const row of promotions) {
    const id = fkId(row.id)
    if (!id) continue
    const dateStart = toDateString(row.date_start)
    const dateEnd = toDateString(row.date_end)
    if (!dateStart || !dateEnd) continue
    if (dateStart > today || dateEnd < today) continue
    const promoType = normalizePromoType(row.promo_type)
    if (!promoType) continue
    activePromotions.push({
      id,
      dateStart,
      dateEnd,
      itemId: fkId(row.item),
      itemGroupId: fkId(row.item_group),
      itemPriceGroupId: fkId(row.price_group) || fkId(row.item_price_group),
      promoType,
      fixedPrice: toNumber(row.fixed_price),
      discountPercent: toNumber(row.discount_percent),
    })
  }

  const itemGroupByItemId = new Map()
  for (const row of items) {
    const id = fkId(row.id)
    if (!id) continue
    itemGroupByItemId.set(id, fkId(row.group) || fkId(row.item_group))
  }

  const patches = []
  let updated = 0
  let cleared = 0
  let unchanged = 0

  for (const row of prices) {
    const id = fkId(row.id)
    if (!id) continue
    const itemId = fkId(row.item)
    const priceGroupId = fkId(row.price_group) || fkId(row.item_price_group)
    const itemGroupId = itemId ? (itemGroupByItemId.get(itemId) ?? null) : null
    const listPrice = toNumber(row.price) ?? 0
    const currentPromotionId = fkId(row.promotion)
    const currentPromoPrice = toNumber(row.promo_price)
    const matches = activePromotions.filter((promo) =>
      promotionMatchesRow(promo, itemId, itemGroupId, priceGroupId),
    )
    const winner = pickWinningPromotion(matches)
    const nextPromotionId = winner ? winner.id : null
    const nextPromoPrice = roundMoney(
      winner ? computePromoPrice(listPrice, winner) : listPrice,
    )
    if (
      sameId(currentPromotionId, nextPromotionId) &&
      sameMoney(currentPromoPrice, nextPromoPrice)
    ) {
      unchanged += 1
      continue
    }
    patches.push({ id, promo_price: nextPromoPrice, promotion: nextPromotionId })
    if (!winner) cleared += 1
    else updated += 1
  }

  return {
    today,
    timeZone,
    patches,
    hasPatches: patches.length > 0,
    summary: {
      activePromotions: activePromotions.length,
      itemPrices: prices.length,
      updated,
      cleared,
      unchanged,
      patchCount: patches.length,
    },
  }
}
